/* a spark: a small zig-zag bolt centred at x,y */
const AE_spark=(x,y,s=1,col)=>`<polyline points="${x-6*s},${y-20*s} ${x+7*s},${y-4*s} ${x-6*s},${y+3*s} ${x+7*s},${y+20*s}" fill="none" stroke="${col||ORG}" stroke-width="${4.5*s}" stroke-linejoin="round" stroke-linecap="round"/>`;
