const AE_wheel=(cx,cy,r,n,col)=>{let s=`<circle cx="${cx}" cy="${cy}" r="${r}" fill="${AE_AL}" stroke="${AE_STEEL}" stroke-width="3"/>`;for(let i=0;i<n;i++){s+=`<rect x="${cx-6}" y="${cy-r-12}" width="12" height="14" rx="2" fill="${col}" transform="rotate(${(360/n*i).toFixed(1)} ${cx} ${cy})"/>`}return s+`<circle cx="${cx}" cy="${cy}" r="8" fill="${AE_DK}"/>`};
